import { useMemo } from 'react';

export function ParamsProvider({ params, children }) {
  const value = useMemo(() => params, [params]);
  return <ParamsContext.Provider value={value}>{children}</ParamsContext.Provider>;
}

import * as React from 'react';
import { useEventStore } from '../stores/events';

export function useVisibleEvents() {
  const storeEvents = useEventStore((s) => s.events);
  return React.useMemo(() => storeEvents, [storeEvents]);
}

import { useMemo } from 'react';

export const TabButton = ({ id, activeId, label }) => {
  const isActive = useMemo(() => id === activeId, [id, activeId]);
  return <button aria-pressed={isActive}>{label}</button>;
};

import { useMemo as memoize } from 'react';

export function Timeline({ left, right }: { left: number; right: number }) {
  const width = memoize(() => right - left, [left, right]);
  return <div style={{ width }} />;
}

import React, { useMemo } from 'react';

export function SplitView({ panes }: { panes?: string[] }) {
  const isSplit = useMemo(() => panes?.length > 1, [panes]);
  return <div className={isSplit ? 'split' : 'single'} />;
}

import React from 'react';

export default function Toggle({ disabled }) {
  const enabled = React.useMemo(function () {
    return !disabled;
  }, [disabled]);
  return <input type="checkbox" disabled={!enabled} />;
}

import { useMemo } from 'react';

export function Badge({ theme, darkColor, lightColor }) {
  const color = useMemo(() => {
    return theme === 'dark' ? darkColor : lightColor;
  }, [theme, darkColor, lightColor]);
  return <span style={{ color }} />;
}

import { useMemo } from 'react';

export function UserName({ user }: { user: { name: string } }) {
  const name = useMemo(() => user.name, [user]);
  return <strong>{name}</strong>;
}

import { useMemo } from 'react';

export function UserTitle({ user }: { user: { title: string } }) {
  const title = useMemo(() => user.title, [user.title]);
  return <h2>{title}</h2>;
}

import { useMemo } from 'react';

type Params = { id: string };

export function RouteParams({ params, children }: { params: Params; children: React.ReactNode }) {
  const value = useMemo<Params>(() => params, [params]);
  return <Ctx.Provider value={value}>{children}</Ctx.Provider>;
}

import { useMemo } from 'react';

export function useProgress(done: number, total: number) {
  return useMemo(() => (total > 0 ? (done / total) * 100 : 0), [done, total]);
}

import * as R from 'react';

export function Compare({ a, b }: { a: string; b: string }) {
  const same = R.useMemo(() => a === b, [a, b]);
  return <span>{same ? 'same' : 'different'}</span>;
}

import React from 'react';

const { useMemo } = React;

export function Sum({ a, b }) {
  const total = useMemo(() => a + b, [a, b]);
  return <output>{total}</output>;
}

import * as R from 'react';

const { useMemo: memo } = R;

export function Label({ text }: { text: string }) {
  const shown = memo(() => text, [text]);
  return <label>{shown}</label>;
}

import { useMemo } from 'react';

export function EmptyState({ count }: { count: number }) {
  const isEmpty = useMemo(() => {
    // nothing to list yet
    return count === 0;
  }, [count]);
  return isEmpty ? <p>No items</p> : null;
}

import { useMemo } from 'react';

type Row = { id: string };

export function Rows({ data }: { data: unknown }) {
  const rows = useMemo<Row[]>(() => data as Row[], [data]);
  return <Grid rows={rows} />;
}

import { useMemo } from 'react';

export function Anchor({ node }: { node: HTMLElement | null }) {
  const el = useMemo(() => node!, [node]);
  return <Popover anchor={el} />;
}

import { useMemo } from 'react';
import { useAbilities } from './useAbilities';

export function useAbility(action: string) {
  const all = useAbilities();
  return useMemo(() => all[action], [all, action]);
}

