import { useMemo } from 'react';

export function useFeedback(rawFeedbackEvents?: string[]) {
  // Re-read only when the count changes, not on every new array.
  // eslint-disable-next-line react-hooks/exhaustive-deps
  return useMemo(() => rawFeedbackEvents, [rawFeedbackEvents?.length]);
}

import { useMemo, useRef } from 'react';

export function useInitialHeight() {
  const ref = useRef<HTMLDivElement>(null);
  const height = useMemo(() => ref.current?.offsetHeight, []);
  return { ref, height };
}

import { useMemo } from 'react';

export function Tags({ tags }: { tags: string[] }) {
  const stable = useMemo(() => tags, [tags?.join(',')]);
  return <TagList tags={stable} />;
}

import { useMemo } from 'react';

export function Checklist({ items }: { items: { done: boolean }[] }) {
  const anyDone = useMemo(() => items.some((i) => i.done), [items]);
  return <p>{anyDone ? 'started' : 'not started'}</p>;
}

import { useMemo } from 'react';

export function Swatch({ color }: { color: string }) {
  const style = useMemo(() => ({ color }), [color]);
  return <Preview style={style} />;
}

import { useMemo } from 'react';

export function Key({ a, b }: { a: string; b: string }) {
  const key = useMemo(() => `${a}-${b}`, [a, b]);
  return <Row id={key} />;
}

import { useMemo, useRef } from 'react';

export function Counter({ step }: { step: number }) {
  const baseRef = useRef(0);
  const start = useMemo(() => baseRef.current + step, [step]);
  return <span>{start}</span>;
}

import { useMemo } from 'preact/hooks';

export function Score({ points, max }: { points: number; max: number }) {
  const ratio = useMemo(() => points / max, [points, max]);
  return <span>{ratio}</span>;
}

import { useMemo } from 'react';

export function useLoader(url: string) {
  return useMemo(async () => url, [url]);
}

import { useMemo } from 'react';

export function Width({ left, right }: { left: number; right: number }) {
  const width = useMemo(() => Math.max(right - left, 0), [left, right]);
  return <div style={{ width }} />;
}

